    ('code', 'Cập nhật lịch ôn sau mỗi lần trả lời (trích từ mô-đun ôn tập ngắt quãng)',
     'export function review(rec, quality) {\n  const q = Math.max(0, Math.min(5, quality));\n  let { ease, interval, reps, lapses } = rec;\n  if (q < 3) {\n    reps = 0;\n    interval = 1;\n    lapses += 1;\n  } else {\n    reps += 1;\n    if (reps === 1) interval = 1;\n    else if (reps === 2) interval = 6;\n    else interval = Math.round(interval * ease);\n  }\n  ease = Math.max(1.3, ease + (0.1 - (5 - q) * 0.08));\n  return { ...rec, ease, interval, reps, lapses };\n}'),
